create table xxcus.xxfnd_wf_delegations (
    delegation_id         number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    delegator_user_name   varchar2(255 byte) not null enable,
    delegate_user_name    varchar2(255 byte) not null enable,
    task_definition       varchar2(255 byte),
    start_date            date not null enable,
    end_date              date not null enable,
    reason                varchar2(1000 byte),
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_wf_delegations
    add constraint xxfnd_wf_delegations_ck1 check ( end_date >= start_date ) enable;

alter table xxcus.xxfnd_wf_delegations
    add constraint xxfnd_wf_delegations_ck2 check ( delegator_user_name <> delegate_user_name ) enable;

alter table xxcus.xxfnd_wf_delegations
    add constraint xxfnd_wf_delegations_pk primary key ( delegation_id )
        using index enable;


